package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AllowAllScopesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property allow all scopes of trusted client ")
  void test_allow_all_scopes_v_o_builder() {
    Assertions.assertFalse(AllowAllScopesVO.nullValue().isAllowAllScopes(),
        "A empty vo should have a null value");
    Assertions.assertFalse(AllowAllScopesVO.tryFrom(null).isAllowAllScopes(),
        "With a null value, no present result");
    Assertions.assertEquals(true, AllowAllScopesVO.from(true).isAllowAllScopes());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> AllowAllScopesVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", AllowAllScopesVO.from(true).toString());
  }
}
